from __future__ import annotations

import datetime as dt
import os
import zipfile

import polars as pl
import pytest
from ds.data.raw import char_ranking

NOV = dt.date(2026, 11, 30)
HEADER = "rank,tag,rating,country,id,Is solo main\n"


def _zip(path, entries):
    with zipfile.ZipFile(path, "w") as archive:
        for name, text in entries.items():
            archive.writestr(name, text)
    return path


@pytest.fixture
def release(tmp_path):
    """A zip like the November 2026 download (one month folder, '<name> ranking.csv' files)"""
    return _zip(
        tmp_path / "November 2026-20261116T044304Z-1-001.zip",
        {
            "November 2026/Cloud ranking.csv": HEADER + '1,Sparg0,10.1k,mx,158026,False\n2,Shady,"1,258",US,1,True\n',
            "November 2026/Peach-Daisy ranking.csv": HEADER + '1,MuteAce,"6,262",us,44865,True\n',
            "November 2026/Random ranking.csv": HEADER + "1,rm8,642.2,ca,1006473,False\n",
            "November 2026/Kazuya Mishima ranking.csv": HEADER + "1,Kaz,3.787,jp,2,True\n",
        },
    )


def test_month_end():
    assert char_ranking.month_end(dt.date(2026, 11, 15)) == NOV
    assert char_ranking.month_end(dt.date(2028, 2, 1)) == dt.date(2028, 2, 29)  # a leap year
    assert char_ranking.month_end(dt.date(2026, 12, 31)) == dt.date(2026, 12, 31)


def test_the_newest_zip_in_downloads_is_the_default(tmp_path):
    downloads = tmp_path / "Downloads"
    downloads.mkdir()
    old = _zip(downloads / "old.zip", {"x.csv": "a\n1\n"})
    os.utime(old, (1, 1))  # older than the next one
    newest = _zip(downloads / "November 2026-001.zip", {"November 2026/Cloud ranking.csv": HEADER})
    assert char_ranking.find_zip(downloads=downloads) == newest  # no name: the newest zip
    assert char_ranking.find_zip("old.zip", downloads=downloads) == old  # a name in the folder
    assert char_ranking.find_zip(str(newest), downloads=downloads) == newest  # a path
    with pytest.raises(FileNotFoundError, match=r"nope\.zip"):
        char_ranking.find_zip("nope.zip", downloads=downloads)
    with pytest.raises(FileNotFoundError, match=r"No \.zip files"):
        char_ranking.find_zip(downloads=tmp_path)


def test_the_month_comes_from_the_folder_in_the_zip(release, tmp_path):
    assert char_ranking.release_month(release) == ("November 2026", NOV)
    feb = _zip(tmp_path / "feb.zip", {"February 2028/Cloud ranking.csv": HEADER})
    assert char_ranking.release_month(feb) == ("February 2028", dt.date(2028, 2, 29))
    two = _zip(tmp_path / "two.zip", {"November 2026/a.csv": HEADER, "October 2026/b.csv": HEADER})
    with pytest.raises(ValueError, match="one month folder"):
        char_ranking.release_month(two)
    odd = _zip(tmp_path / "odd.zip", {"Character Rankings/a.csv": HEADER})
    with pytest.raises(ValueError, match="isn't a month"):
        char_ranking.release_month(odd)


def test_a_release_reads_typed_with_our_ids(release):
    df = char_ranking.read_release(release)
    assert df.columns == [
        "date",
        "char_group_id",
        "rank",
        "tag",
        "player_id",
        "country",
        "rating",
        "is_solo_main",
    ]
    assert df.schema["date"] == pl.Date
    assert (df["date"] == NOV).all()
    cloud = df.filter(pl.col("char_group_id") == "cloud")
    assert cloud["tag"].to_list() == ["Sparg0", "Shady"]
    assert cloud["rating"].to_list() == [10100.0, 1258.0]  # '10.1k', '1,258'
    assert cloud["player_id"].to_list() == [158026, 1]  # start.gg ids
    assert cloud["is_solo_main"].to_list() == [False, True]
    assert cloud["country"].to_list() == ["mx", "us"]
    assert df.filter(pl.col("char_group_id") == "kazuya")["rating"].to_list() == [3.787]


def test_echo_pairs_go_to_each_member_and_random_has_no_character(release):
    df = char_ranking.read_release(release)
    pair = df.filter(pl.col("tag") == "MuteAce")  # the Peach-Daisy ranking
    assert sorted(pair["char_group_id"].cast(pl.String).to_list()) == ["daisy", "peach"]
    assert df.filter(pl.col("tag") == "rm8")["char_group_id"].to_list() == [None]  # Random
    # the pick is the key: no two rows of a release share (char_group_id, rank)
    assert df.select("date", "char_group_id", "rank").is_unique().all()


def test_an_unknown_name_or_a_new_column_stops_the_load(tmp_path):
    new_name = _zip(tmp_path / "a.zip", {"November 2026/Goku ranking.csv": HEADER + "1,x,1,us,1,True\n"})
    with pytest.raises(ValueError, match="No character matches the ranking 'Goku'"):
        char_ranking.read_release(new_name)
    new_column = _zip(tmp_path / "b.zip", {"November 2026/Cloud ranking.csv": "rank,tag,score\n1,x,2\n"})
    with pytest.raises(ValueError, match="did the format change"):
        char_ranking.read_release(new_column)


def test_reloading_a_month_replaces_only_that_month(release, tmp_path):
    def month(day, players):
        return pl.DataFrame({"date": [day] * len(players), "tag": players})

    old = month(dt.date(2026, 10, 31), ["a", "b"])
    table = char_ranking.merge_release(old, month(NOV, ["c"]))
    table = char_ranking.merge_release(table, month(NOV, ["d", "e"]))
    assert table["tag"].to_list() == ["d", "e", "a", "b"]  # newest first, the old month kept
    assert char_ranking.merge_release(None, old).equals(old)
    # stored and read back, `date` is still a Date
    path = tmp_path / "char_ranking.parquet"
    char_ranking.merge_release(None, char_ranking.read_release(release)).write_parquet(path)
    assert pl.read_parquet(path).schema["date"] == pl.Date


def test_the_command_says_how_to_get_the_file(tmp_path):
    """--help and a run that finds no zip both show the steps (from _char_ranking_steps)"""
    from ds.cli.data import _char_ranking_steps, data_app
    from typer.testing import CliRunner

    runner = CliRunner()
    shown = " ".join(runner.invoke(data_app, ["char_ranking", "--help"]).output.split())
    assert "SchuStats Discord" in shown
    assert "Character Rankings" in shown
    missing = runner.invoke(data_app, ["char_ranking", str(tmp_path / "none.zip")])
    assert missing.exit_code == 1
    assert _char_ranking_steps()[0] in missing.output
